/**
 * Free-access codes. Generated by the owner CLI (scripts/access-code.mjs) as 12 characters from an unambiguous
 * alphabet (≈59 bits), shown as XXXX-XXXX-XXXX. Custom codes (6–24 letters/digits) are allowed too.
 * Only SHA-256("bz-access:" + normalised code) is stored; scripts/access-code.mjs implements the same hash
 * (tests/unit/billing-codes.test.ts checks both agree).
 */
export const ACCESS_CODE_PREFIX = "bz-access:";

/** Upper-case, drop spaces/dashes/punctuation. Returns null unless 6–24 letters/digits remain. */
export function normaliseAccessCode(x: unknown): string | null {
  if (typeof x !== "string" || x.length > 64) return null;
  const s = x.toUpperCase().replace(/[^0-9A-Z]/g, "");
  return s.length >= 6 && s.length <= 24 ? s : null;
}

export async function hashAccessCode(normalised: string): Promise<string> {
  const buf = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(ACCESS_CODE_PREFIX + normalised));
  return [...new Uint8Array(buf)].map((b) => b.toString(16).padStart(2, "0")).join("");
}
